/** C: objects[] oclass for exported rows; 0 when absent (do not use for mklev mksobj_init until floor parity verified). */
export function nh5OclassFromOcSkillMapLikeC(otyp) {
    return OC_SKILL_ROW_BY_OTYP.get(otyp | 0)?.oclass ?? 0;
}

/** C: objects[otyp].oc_class — full table for obj_to_glyph / map_object. */
export function nh5OclassFromObjectsLikeC(otyp) {
    return OC_CLASS_BY_OTYP.get(otyp | 0) ?? 0;
}

/** C: objects[otyp].oc_color when iflags.use_color — null when unset. */
export function nh5ObjColorFromObjectsLikeC(otyp) {
    const c = OC_COLOR_BY_OTYP.get(otyp | 0);
    return c == null ? null : (c | 0);
}
